// lib/game/author-extension.ts
function resolveRecordSchema2(reference, schemas) {
  if (reference.includes("@")) return schemas.find((item) => item.id + "@" + item.version === reference);
  const matches = schemas.filter((item) => item.id === reference);
  if (matches.length > 1) throw new Error("extension\uFF1A\u8BB0\u5F55\u7C7B\u578B\u7248\u672C\u4E0D\u660E\u786E");
  return matches[0];
}
function authorValueSchemas(type, schemas) {
  const selected = [];
  const visit = (value) => {
    if (typeof value === "string") return;
    if (value.kind === "list" || value.kind === "set") return visit(value.element);
    if (value.kind === "map") {
      visit(value.key);
      visit(value.value);
      return;
    }
    if (value.kind === "nullable") return visit(value.value);
    const schema3 = resolveRecordSchema2(value.schema, schemas);
    if (!schema3) throw new Error("extension\uFF1A\u8BB0\u5F55\u7C7B\u578B\u5C1A\u672A\u58F0\u660E");
    if (selected.some((item) => item.id === schema3.id && item.version === schema3.version)) return;
    selected.push(schema3);
    schema3.fields.forEach((field3) => visit(field3.type));
    if (schema3.additionalFields) visit(schema3.additionalFields);
  };
  visit(type);
  return selected.sort((a, b) => (a.id + "@" + a.version).localeCompare(b.id + "@" + b.version));
}

